import numpy as np


class AdaptiveMomentumDE:
    """
    LPSR SHADE feasibility DE with refined momentum pattern search and success-adaptive restarts.
      * LPSR schedule, Deb feasibility rules, current-to-pbest/1 with external archive.
      * SHADE success-history memory for F and CR, evaluation cache (repeated points are free).
      * Momentum pattern search: coordinate probes, then repeated doubling extrapolation along the
        net successful displacement while it keeps improving.
      * Diversified feasible elite pool; restarts are Cauchy-jittered clouds around elites.
        A restart radius that produced an incumbent improvement is reused, otherwise radii cycle.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        budget = self.budget

        lb = np.asarray(func.bounds.lb, dtype=float).reshape(-1)[:d]
        ub = np.asarray(func.bounds.ub, dtype=float).reshape(-1)[:d]
        span = ub - lb
        span_safe = np.where(span > 0, span, 1.0)
        vtypes = [str(t) for t in func.variable_types][:d]
        is_int = np.array([t != "continuous" for t in vtypes])
        is_cat = np.array([t == "categorical" for t in vtypes])
        nv = np.ones(d)
        if hasattr(func, "n_values"):
            nv = np.where(is_int, np.asarray(func.n_values, dtype=float)[:d], 1.0)
        int_idx = np.where(is_int)[0]
        cont_idx = np.where(~is_int)[0]

        state = {"evals": 0}
        cache = {}
        best = {"f": np.inf, "x": None, "feas": False}
        fb = {"viol": np.inf, "x": None}
        elites = []

        def decode(u):
            x = lb + u * span
            if int_idx.size:
                x[int_idx] = np.clip(np.rint(x[int_idx]), 0, nv[int_idx] - 1)
            return x

        def evaluate(u):
            u = np.clip(u, 0.0, 1.0)
            x = decode(u)
            k = x.tobytes()
            if k in cache:
                r = cache[k]
                return {"u": u.copy(), "f": r["f"], "viol": r["viol"], "feas": r["feas"]}
            f, g = func(x)
            state["evals"] += 1
            f = float(f)
            g = np.nan_to_num(np.atleast_1d(np.asarray(g, dtype=float)),
                              nan=1e10, posinf=1e10, neginf=0.0)
            finite = np.isfinite(f)
            feas = bool(finite and np.all(g <= 0))
            if feas:
                viol = 0.0
                if f < best["f"]:
                    best.update(f=f, x=x.copy(), feas=True)
            else:
                viol = float(np.sum(np.maximum(g, 0.0))) if finite else 1e10
                viol = max(viol, 1e-12)
                if viol < fb["viol"]:
                    fb.update(viol=viol, x=x.copy())
            fv = f if finite else np.inf
            r = {"u": u.copy(), "f": fv, "viol": viol, "feas": feas}
            cache[k] = r
            if feas:
                add_elite(u, fv)
            return r

        def add_elite(u, f):
            for e in elites:
                if np.max(np.abs(e["u"] - u)) < 5e-3:
                    if f < e["f"]:
                        e["u"], e["f"] = u.copy(), f
                    return
            elites.append({"u": u.copy(), "f": f})
            elites.sort(key=lambda e: e["f"])
            del elites[16:]

        def better(a, b):
            if a["feas"] and b["feas"]:
                return a["f"] < b["f"]
            if a["feas"] != b["feas"]:
                return a["feas"]
            return a["viol"] < b["viol"]

        def rank_key(e):
            return (0, e["f"]) if e["feas"] else (1, e["viol"])

        def lhs(n):
            if n <= 0:
                return np.zeros((0, d))
            cut = (np.arange(n)[:, None] + rng.random((n, d))) / n
            for j in range(d):
                cut[:, j] = cut[rng.permutation(n), j]
            return cut

        def sample_F(mu):
            for _ in range(20):
                v = mu + 0.1 * np.tan(np.pi * (rng.random() - 0.5))
                if v > 0:
                    return min(v, 1.0)
            return 0.5

        def sample_CR(mu):
            return float(np.clip(rng.normal(mu, 0.1), 0.0, 1.0))

        def mutate_discrete(v):
            for k in int_idx:
                if rng.random() < 1.0 / max(1, d):
                    if is_cat[k]:
                        v[k] = (rng.integers(int(nv[k])) + 0.5) / nv[k]
                    else:
                        if rng.random() < 0.7:
                            lvl = int(np.floor(v[k] * nv[k]))
                            lvl = int(np.clip(lvl + rng.choice([-1, 1]), 0, nv[k] - 1))
                        else:
                            lvl = int(rng.integers(int(nv[k])))
                        v[k] = (lvl + 0.5) / nv[k]
            return v

        steps = np.full(d, 0.05)

        def refine(e, max_evals):
            """Coordinate probes followed by repeated doubling extrapolation along success direction."""
            cur = e
            cnt = 0
            start_u = e["u"].copy()
            for k in rng.permutation(d):
                if cnt >= max_evals or state["evals"] >= budget:
                    break
                if is_int[k]:
                    lvl = int(np.clip(np.floor(cur["u"][k] * nv[k]), 0, nv[k] - 1))
                    for L in (lvl - 1, lvl + 1):
                        if cnt >= max_evals or state["evals"] >= budget:
                            break
                        if 0 <= L <= nv[k] - 1:
                            u2 = cur["u"].copy()
                            u2[k] = (L + 0.5) / nv[k]
                            r = evaluate(u2)
                            cnt += 1
                            if better(r, cur):
                                cur = r
                                break
                else:
                    s = steps[k]
                    improved = False
                    for sign in (1.0, -1.0):
                        if cnt >= max_evals or state["evals"] >= budget:
                            break
                        u2 = cur["u"].copy()
                        u2[k] = float(np.clip(cur["u"][k] + sign * s, 0.0, 1.0))
                        if u2[k] == cur["u"][k]:
                            continue
                        r = evaluate(u2)
                        cnt += 1
                        if better(r, cur):
                            cur = r
                            improved = True
                            break
                    steps[k] = min(0.25, s * 1.5) if improved else max(1e-3, s * 0.6)

            # repeated extrapolation along net displacement, doubling while it keeps improving
            if cont_idx.size and cnt < max_evals and state["evals"] < budget:
                disp = cur["u"] - start_u
                if np.linalg.norm(disp[cont_idx]) > 1e-9:
                    scale = rng.uniform(1.0, 2.0)
                    for _ in range(3):
                        if cnt >= max_evals or state["evals"] >= budget:
                            break
                        u2 = cur["u"].copy()
                        u2[cont_idx] = np.clip(cur["u"][cont_idx] + scale * disp[cont_idx], 0.0, 1.0)
                        r = evaluate(u2)
                        cnt += 1
                        if better(r, cur):
                            disp = r["u"] - cur["u"]
                            cur = r
                            scale *= 2.0
                        else:
                            break
                # random direction probe for continuous variables
                if cnt < max_evals and state["evals"] < budget:
                    dirv = rng.normal(size=cont_idx.size)
                    dirv /= (np.linalg.norm(dirv) + 1e-12)
                    u2 = cur["u"].copy()
                    u2[cont_idx] = np.clip(u2[cont_idx] + 0.05 * dirv, 0.0, 1.0)
                    r = evaluate(u2)
                    if better(r, cur):
                        cur = r
            return cur

        # ---------- initialisation ----------
        NP0 = max(10, 5 * d)
        NP0 = min(NP0, max(4, budget // 4))
        pop = []
        for u in lhs(NP0):
            if state["evals"] >= budget:
                break
            pop.append(evaluate(u))
        if len(pop) < 4:
            if best["x"] is not None:
                return best["f"], best["x"]
            return np.inf, fb["x"]

        NP = len(pop)
        NP0 = NP
        H = 6
        MF = np.full(H, 0.5)
        MCR = np.full(H, 0.8)
        mem_k = 0
        archive = []
        run_start = state["evals"]
        last_best = best["f"]
        gen_no_improve = 0
        stagn_limit = 10 + 2 * d
        restart_id = 0
        radii = [0.2, 0.05, 0.01]
        cur_rad = radii[0]
        idle_gens = 0

        while state["evals"] < budget and NP >= 4:
            ev_before = state["evals"]

            frac = min(1.0, (state["evals"] - run_start) / max(1, budget - run_start))
            NP_target = max(4, int(round(NP0 + (4 - NP0) * frac)))
            if NP_target < NP:
                pop.sort(key=rank_key)
                pop = pop[:NP_target]
                NP = len(pop)
                archive = archive[-NP:] if len(archive) > NP else archive

            order = sorted(range(NP), key=lambda i: rank_key(pop[i]))
            p = max(2, int(0.15 * NP))
            S_F, S_CR, S_w = [], [], []
            incumbent_improved = False
            replaced = []

            for i in range(NP):
                if state["evals"] >= budget:
                    break
                r_idx = rng.integers(H)
                F = sample_F(MF[r_idx])
                CR = sample_CR(MCR[r_idx])

                xi = pop[i]["u"]
                pb = pop[order[rng.integers(p)]]["u"]
                r1 = rng.integers(NP - 1)
                r1 = r1 + 1 if r1 >= i else r1
                pool_extra = len(archive)
                if pool_extra > 0 and rng.random() < pool_extra / (pool_extra + NP):
                    xr2 = archive[rng.integers(pool_extra)]
                else:
                    r2 = rng.integers(NP - 1)
                    r2 = r2 + 1 if r2 >= i else r2
                    xr2 = pop[r2]["u"]
                xr1 = pop[r1]["u"]
                v = xi + F * (pb - xi) + F * (xr1 - xr2)

                mask = rng.random(d) < CR
                mask[rng.integers(d)] = True
                trial = np.clip(np.where(mask, v, xi), 0.0, 1.0)
                trial = mutate_discrete(trial)

                t = evaluate(trial)
                if better(t, pop[i]):
                    if t["feas"] and pop[i]["feas"]:
                        delta = max(pop[i]["f"] - t["f"], 1e-12)
                    elif (not t["feas"]) and (not pop[i]["feas"]):
                        delta = max(pop[i]["viol"] - t["viol"], 1e-12)
                    else:
                        delta = 1.0
                    if t["feas"] and not pop[i]["feas"]:
                        incumbent_improved = True
                    S_F.append(F)
                    S_CR.append(CR)
                    S_w.append(delta)
                    replaced.append(pop[i]["u"].copy())
                    pop[i] = t

            for u in replaced:
                archive.append(u)
            while len(archive) > NP:
                archive.pop(rng.integers(len(archive)))

            if S_F:
                w = np.asarray(S_w, dtype=float)
                w = w / (w.sum() + 1e-300)
                sF = np.asarray(S_F)
                sCR = np.asarray(S_CR)
                meanF = np.sum(w * sF ** 2) / (np.sum(w * sF) + 1e-300)
                meanCR = np.sum(w * sCR)
                MF[mem_k] = 0.5 * MF[mem_k] + 0.5 * meanF
                MCR[mem_k] = 0.5 * MCR[mem_k] + 0.5 * meanCR
                mem_k = (mem_k + 1) % H

            if state["evals"] < budget:
                bi = min(range(NP), key=lambda i: rank_key(pop[i]))
                if pop[bi]["feas"]:
                    if incumbent_improved:
                        refined = refine(pop[bi], max_evals=2 * d + 4)
                        if better(refined, pop[bi]):
                            pop[bi] = refined
                elif fb["x"] is not None and gen_no_improve % 3 == 0:
                    anchor = evaluate((fb["x"] - lb) / span_safe)
                    refined = refine(anchor, max_evals=d + 2)
                    if better(refined, pop[bi]):
                        pop[bi] = refined

            if best["f"] < last_best - 1e-12:
                last_best = best["f"]
                gen_no_improve = 0
            else:
                gen_no_improve += 1

            if state["evals"] == ev_before:
                idle_gens += 1
            else:
                idle_gens = 0

            spread = np.mean(np.std(np.array([q["u"] for q in pop]), axis=0))
            stalled = gen_no_improve >= stagn_limit or spread < 1e-3 or idle_gens >= 20
            if stalled and state["evals"] < budget:
                bi = min(range(NP), key=lambda i: rank_key(pop[i]))
                keep = pop[bi]
                new_pop = [keep]
                n_new = max(4, min(NP0, (budget - state["evals"]) // 2 + 4))
                prev_best = best["f"]
                if keep["feas"]:
                    rad = cur_rad
                    n_local = n_new // 2
                    for j in range(n_local):
                        if state["evals"] >= budget:
                            break
                        if elites and rng.random() < 0.5:
                            # rank-biased elite choice (better elites more likely)
                            m = len(elites)
                            wts = 1.0 / np.arange(1, m + 1)
                            wts /= wts.sum()
                            base = elites[rng.choice(m, p=wts)]["u"]
                        else:
                            base = keep["u"]
                        u = base.copy()
                        jitter = rad * np.tan(np.pi * (rng.random(cont_idx.size) - 0.5)) \
                            if cont_idx.size else np.zeros(0)
                        jitter = np.clip(jitter, -0.5, 0.5)
                        u[cont_idx] = u[cont_idx] + jitter
                        for k in int_idx:
                            if rng.random() < 0.2:
                                u[k] = rng.random()
                        new_pop.append(evaluate(np.clip(u, 0.0, 1.0)))
                    restart_radius_used = cur_rad
                else:
                    n_local = 0
                    restart_radius_used = None
                for u in lhs(max(n_new - n_local, 0)):
                    if state["evals"] >= budget:
                        break
                    new_pop.append(evaluate(u))

                # success-adaptive radius: keep radius if it improved the incumbent, else cycle
                if restart_radius_used is not None:
                    if best["f"] < prev_best - 1e-12:
                        pass
                    else:
                        restart_id += 1
                        cur_rad = radii[restart_id % len(radii)]
                else:
                    restart_id += 1
                    cur_rad = radii[restart_id % len(radii)]

                pop = new_pop
                NP = len(pop)
                if NP < 4:
                    break
                NP0 = NP
                run_start = state["evals"]
                MF = np.full(H, 0.5)
                MCR = np.full(H, 0.8)
                archive = []
                steps = np.full(d, 0.05)
                gen_no_improve = 0
                idle_gens = 0
                last_best = best["f"]

        if best["x"] is None:
            return np.inf, fb["x"]
        return best["f"], best["x"]
